function vpListenOnce(onResult,onError){
  try{
    var SR=window.SpeechRecognition||window.webkitSpeechRecognition;
    if(!SR){toast('Reconhecimento de voz não disponível neste navegador/aparelho',false);if(onError)onError();return function(){};}
    var r=new SR();
    var done=false;
    r.lang='pt-BR';r.continuous=false;r.interimResults=false;r.maxAlternatives=1;
    var timer=setTimeout(function(){
      if(done)return;done=true;
      try{r.abort();}catch(e){}
      if(onError)onError({error:'timeout'});
    },6000);
    function finish(fn,arg){if(done)return;done=true;clearTimeout(timer);try{fn(arg);}catch(e){}}
    r.onresult=function(e){
      var t=(e.results&&e.results[0]&&e.results[0][0])?e.results[0][0].transcript:'';
      finish(onResult,t||'');
    };
    r.onerror=function(e){finish(onError,e);};
    r.onend=function(){finish(onError,{error:'no-speech'});};
    try{r.start();}catch(e){finish(onError,e);}
    return function cancel(){if(done)return;done=true;clearTimeout(timer);try{r.abort();}catch(e){}};
  }catch(e){if(onError)onError(e);return function(){};}
}
