      +'</div>'
      +'<div class="two">'
        +'<div class="panel"><div class="ph" style="display:flex;align-items:center;justify-content:space-between"><span><span class="pdot"></span>Bipar etiqueta</span>'
          +'<span class="modeSeg" id="floorModeSeg"><button type="button" class="on" data-mode="add">Entrada</button><button type="button" data-mode="out">Saída</button></span></div>'
          +'<label class="fld"><span class="lab" id="floorScanLab">Etiqueta (T…)</span><input class="input code" id="floorScan" placeholder="ex: T40364663"></label>'
          +'<p id="floorScanHint" style="color:var(--muted);font-size:.8rem;margin:0;line-height:1.5">Cada bipe soma <b>+1 bobina</b> e o <b>peso</b> no código. Bipou outra etiqueta do <b>mesmo código</b>? Acumula tudo junto. A mesma etiqueta não conta duas vezes.</p></div>'
        +'<div class="panel" style="display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center">'
          +'<div style="font-family:var(--disp);font-size:3rem;font-weight:800;line-height:1">'+t.q+'</div>'
          +'<div style="font-size:.6rem;letter-spacing:1px;text-transform:uppercase;color:var(--muted);font-weight:700;margin-top:4px">bobinas no chão</div>'
          +(t.q?'<div style="font-family:var(--mono);font-size:.85rem;color:var(--muted);margin-top:8px">'+fmt(t.kg)+' kg · '+t.codes+' '+(t.codes===1?'código':'códigos')+'</div>':'')
        +'</div>'
      +'</div><h3 class="sub">Totais por código</h3><div id="floorList"></div>';
    const sc=$('#floorScan');
    if(sc){
      var _floorMode=function(){return (window._floorScanMode==='out')?window.floorSaida:window.floorAdd;};
      sc.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();_floorMode()(sc.value);sc.value='';}});
      sc.placeholder=isSuper()?'bipe ou digite':'toque para bipar';scanLock(sc);
      if(window.addCam)addCam('floorScan',{continuous:true,onResult:function(v){_floorMode()(v);},title:'Escanear bobinas'});
    }
    /* seletor Entrada/Saída */
    (function(){var seg=document.getElementById('floorModeSeg');if(!seg)return;window._floorScanMode=window._floorScanMode||'add';
      seg.querySelectorAll('button').forEach(function(b){b.classList.toggle('on',b.dataset.mode===window._floorScanMode);b.onclick=function(){window._floorScanMode=b.dataset.mode;seg.querySelectorAll('button').forEach(function(x){x.classList.toggle('on',x===b);});
        var hint=document.getElementById('floorScanHint');var lab=document.getElementById('floorScanLab');var inp=document.getElementById('floorScan');
        if(window._floorScanMode==='out'){if(hint)hint.innerHTML='Modo <b style="color:#dc2626">SAÍDA</b>: cada bipe <b>remove</b> aquela bobina do chão e registra a saída no histórico.';if(lab)lab.textContent='Etiqueta que está saindo';if(inp)inp.placeholder='bipe a etiqueta da saída';}
        else{if(hint)hint.innerHTML='Cada bipe soma <b>+1 bobina</b> e o <b>peso</b> no código. A mesma etiqueta não conta duas vezes.';if(lab)lab.textContent='Etiqueta (T…)';if(inp)inp.placeholder=(typeof isSuper==='function'&&isSuper())?'bipe ou digite':'toque para bipar';}
        if(inp)try{inp.focus();}catch(e){}
      };});
    })();
