    var _orig=window.renderFloor;
    window.renderFloor=function(){var r=_orig.apply(this,arguments);try{var av=document.querySelector('.view.active');if(av&&av.id==='v-recic'&&typeof renderRecic==='function')renderRecic();}catch(e){}return r;};
