/* ===== CAMADA FINAL DE SEGURANÇA E DIAGNÓSTICO ===== */
(function(){
  function registrarFalha(tipo,erro){
    try{
      window._DIAG=window._DIAG||{};
      var msg=String((erro&&erro.message)||erro||'erro desconhecido');
      window._DIAG.ultimaFalha={tipo:tipo,mensagem:msg,at:new Date().toISOString()};
      var hist=JSON.parse(localStorage.getItem('wmsx_error_audit')||'[]');
      hist.push(window._DIAG.ultimaFalha);if(hist.length>200)hist=hist.slice(-200);
      localStorage.setItem('wmsx_error_audit',JSON.stringify(hist));
    }catch(_e){}
  }
  window.addEventListener('error',function(e){registrarFalha('javascript',e.error||e.message);});
  window.addEventListener('unhandledrejection',function(e){var msg=String((e.reason&&e.reason.message)||e.reason||'').toLowerCase(),sync=/fetch|network|supabase|sincron|websocket|realtime/.test(msg);registrarFalha(sync?'sincronizacao':'promessa',e.reason);});

  /* senha nunca fica exposta visualmente no cadastro de usuários */
  function protegerSenha(){var p=document.getElementById('uP');if(p){p.type='password';p.autocomplete='new-password';}}
  document.addEventListener('click',function(e){
    var alvo=e.target&&e.target.closest&&e.target.closest('#uDel');
    if(alvo&&!isSuper()){e.preventDefault();e.stopImmediatePropagation();toast('Somente o administrador pode excluir usuários',false);return;}
    setTimeout(protegerSenha,0);
  },true);
  if(window.MutationObserver)new MutationObserver(protegerSenha).observe(document.body,{childList:true,subtree:true});
  protegerSenha();

  /* relatório simples para o administrador verificar falhas de gravação sem alterar dados */
  window.wmsStorageAudit=function(){
    var r={localStorage:'ok',indexedDB:'disponível',falhas:[],diagnostico:window._DIAG||{}};
    try{var k='__wms_test__';localStorage.setItem(k,'1');localStorage.removeItem(k);}catch(e){r.localStorage='falha: '+String(e&&e.message||e);}
    try{r.falhas=JSON.parse(localStorage.getItem('wmsx_error_audit')||'[]');}catch(e){}
    console.table(r.falhas);return r;
  };

  /* UMA ETIQUETA = UM LOCAL FISICO.
     Nenhuma entrada pode retirar a bobina silenciosamente de outro deposito.
     A transferencia correta e sempre: Saida no local atual -> Entrada no novo local. */
  function etiquetaNormalizada(v){
    try{if(typeof window.cleanScanCode==='function')v=window.cleanScanCode(v);}catch(e){}
    try{return typeof norm==='function'?norm(v):String(v||'').trim().toUpperCase();}catch(e){return String(v||'').trim().toUpperCase();}
  }
  function listaTemEtiqueta(estado,et){
    var achou=false;
    try{Object.values(estado||{}).some(function(g){
      var a=(g&&Array.isArray(g.ets))?g.ets:[];
      achou=a.some(function(x){return etiquetaNormalizada(typeof x==='string'?x:x&&x.et)===et;});
      return achou;
    });}catch(e){}
    return achou;
  }
  function ultimoLocalDoChao(et){
    var local='Expedição - 71';
    try{
      var mov=(Array.isArray(MV)?MV:[]).filter(function(m){return etiquetaNormalizada(m&&m.et)===et;})
        .sort(function(a,b){return Date.parse(b.at||0)-Date.parse(a.at||0);});
      for(var i=0;i<mov.length;i++){
        var cod=String(mov[i].code||'').toUpperCase();
        if(cod.indexOf('RECICL')>=0){local='Recicladora - 91';break;}
        if(cod.indexOf('EXPEDI')>=0||cod==='CHÃO'||cod==='CHAO'){local='Expedição - 71';break;}
      }
    }catch(e){}
    return local;
  }
  window.wmsLocalDaEtiqueta=function(v){
    var et=etiquetaNormalizada(v);if(!et)return null;
    try{if(typeof LOC!=='undefined'&&LOC&&LOC[et])return {etiqueta:et,local:'Prateleira - 70',detalhe:String(LOC[et])};}catch(e){}
    try{if(typeof window.recicGetState==='function'&&listaTemEtiqueta(window.recicGetState(),et))return {etiqueta:et,local:'Recicladora - 91',detalhe:''};}catch(e){}
    try{if(typeof window.floor70GetState==='function'&&listaTemEtiqueta(window.floor70GetState(),et))return {etiqueta:et,local:'Chão de Fábrica - 70',detalhe:''};}catch(e){}
    try{if(typeof window.floorGetState==='function'&&listaTemEtiqueta(window.floorGetState(),et))return {etiqueta:et,local:ultimoLocalDoChao(et),detalhe:''};}catch(e){}
    return null;
  };
  function bloquearEntradaDuplicada(v,destino){
    var et=etiquetaNormalizada(v),onde=window.wmsLocalDaEtiqueta(et);
    if(!onde)return false;
    var detalhe=onde.detalhe?' ('+onde.detalhe+')':'';
    toast('Etiqueta '+et+' já está em '+onde.local+detalhe+'. Faça a SAÍDA nesse local antes de dar ENTRADA em '+destino+'.',false);
    return true;
  }
  function destinoChaoCompartilhado(){
    try{return ((document.querySelector('.view.active')||{}).id==='v-recic')?'Recicladora - 91':'Expedição - 71';}catch(e){return 'Expedição - 71';}
  }
  try{
    if(typeof window.floorAdd==='function'&&!window.floorAdd._localUnico){
      var entradaChao=window.floorAdd;
      var travaChao=async function(v){if(bloquearEntradaDuplicada(v,destinoChaoCompartilhado()))return false;return entradaChao.apply(this,arguments);};
      travaChao._localUnico=true;window.floorAdd=travaChao;
    }
  }catch(e){registrarFalha('trava-etiqueta-chao',e);}
  try{
    if(typeof window.floor70Add==='function'&&!window.floor70Add._localUnico){
      var entradaFabrica=window.floor70Add;
      var travaFabrica=async function(v){if(bloquearEntradaDuplicada(v,'Chão de Fábrica - 70'))return false;return entradaFabrica.apply(this,arguments);};
      travaFabrica._localUnico=true;window.floor70Add=travaFabrica;
    }
  }catch(e){registrarFalha('trava-etiqueta-fabrica',e);}
  try{
    if(typeof window.f70Entrada==='function'&&!window.f70Entrada._localUnico){
      var entradaRecebimentoFabrica=window.f70Entrada;
      var travaRecebimentoFabrica=function(it){
        var et=it&&it.et;
        /* Estar no intermediario nao e duplicidade fisica; estar em qualquer deposito e. */
        if(bloquearEntradaDuplicada(et,'Chão de Fábrica - 70'))return false;
        return entradaRecebimentoFabrica.apply(this,arguments);
      };
      travaRecebimentoFabrica._localUnico=true;window.f70Entrada=travaRecebimentoFabrica;
    }
  }catch(e){registrarFalha('trava-etiqueta-recebimento',e);}
  try{
    if(typeof placeBobina==='function'&&!placeBobina._localUnico){
      var entradaPrateleira=placeBobina;
      var travaPrateleira=function(et,pr,pl,c){if(bloquearEntradaDuplicada(et,'Prateleira - 70'+(c?' ('+c+')':'')))return false;return entradaPrateleira.apply(this,arguments);};
      travaPrateleira._localUnico=true;placeBobina=travaPrateleira;window.placeBobina=travaPrateleira;
    }
  }catch(e){registrarFalha('trava-etiqueta-prateleira',e);}
  try{
    if(typeof recvAdd==='function'&&!recvAdd._localUnico){
      var entradaRecebimento=recvAdd;
      var travaRecebimento=async function(v){
        if(bloquearEntradaDuplicada(v,'Recebimento / Estoque intermediário'))return false;
        return entradaRecebimento.apply(this,arguments);
      };
      travaRecebimento._localUnico=true;recvAdd=travaRecebimento;window.recvAdd=travaRecebimento;
    }
  }catch(e){registrarFalha('trava-etiqueta-estoque-intermediario',e);}
})();

/* ===== CONSULTA DE ETIQUETA ===== */
(function(){
  var main=document.querySelector('main');if(!main||document.getElementById('v-etqconsulta'))return;
  var sec=document.createElement('section');sec.className='view';sec.id='v-etqconsulta';main.appendChild(sec);
  if(typeof TITLES!=='undefined')TITLES['v-etqconsulta']='Consulta de Etiqueta';
  var ref=[].slice.call(document.querySelectorAll('.nav')).find(function(n){return n.dataset.view==='v-labels';});
  var nav=document.createElement('div');nav.className='nav';nav.dataset.view='v-etqconsulta';nav.innerHTML='<span class="ni"></span>Consulta de Etiqueta';
  if(ref&&ref.parentNode)ref.parentNode.insertBefore(nav,ref.nextSibling);else{var side=document.querySelector('.sidebar');if(side)side.appendChild(nav);}
  nav.onclick=function(){go('v-etqconsulta');};
  var css=document.createElement('style');css.textContent=
    '#v-etqconsulta .ec-head{margin-bottom:18px}#v-etqconsulta .ec-head h1{margin:4px 0;font-size:1.65rem}#v-etqconsulta .ec-head p{margin:0;color:var(--muted);font-size:.8rem}'
   +'#v-etqconsulta .ec-search{background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px;box-shadow:var(--sh-sm);display:grid;grid-template-columns:1fr 150px;gap:10px}'
   +'#v-etqconsulta .ec-search .input{height:50px;font:800 1rem var(--mono);letter-spacing:.04em}#v-etqconsulta .ec-go{border:0;border-radius:11px;background:var(--brand);color:#fff;font-weight:800;cursor:pointer}'
   +'#v-etqconsulta .ec-result{margin-top:16px}.ec-card{background:#fff;border:1px solid var(--line);border-top:4px solid var(--brand);border-radius:16px;padding:20px;box-shadow:var(--sh-sm)}'
   +'.ec-top{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;flex-wrap:wrap}.ec-et{font:900 1.35rem var(--mono)}.ec-actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.ec-status{display:inline-flex;border-radius:20px;padding:5px 10px;background:#ecfdf5;color:#047857;font-size:.68rem;font-weight:900}.ec-print{height:36px;border:1px solid var(--line-2);border-radius:9px;background:#fff;color:var(--ink);padding:0 13px;font-weight:800;font-size:.72rem;cursor:pointer}.ec-print:hover{border-color:var(--brand);color:var(--brand)}'
   +'.ec-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:18px}.ec-info{background:var(--card-2);border:1px solid var(--line);border-radius:11px;padding:13px}.ec-info span{display:block;color:var(--muted);font-size:.61rem;text-transform:uppercase;font-weight:800;letter-spacing:.06em}.ec-info b{display:block;margin-top:5px;font-size:.85rem;word-break:break-word}.ec-desc{margin-top:12px;padding:14px;border-left:3px solid var(--brand);background:#fff7ed;border-radius:8px;font-size:.84rem}.ec-empty{text-align:center;padding:48px 20px;background:#fff;border:1px dashed var(--line-2);border-radius:16px;color:var(--muted)}'
   +'@media(max-width:850px){#v-etqconsulta .ec-grid{grid-template-columns:1fr 1fr}}@media(max-width:560px){#v-etqconsulta .ec-search{grid-template-columns:1fr}.ec-go{height:46px}#v-etqconsulta .ec-grid{grid-template-columns:1fr}}';document.head.appendChild(css);
  function h(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
  function dataHora(v){if(!v)return 'Não registrada';try{return new Date(v).toLocaleString('pt-BR');}catch(e){return String(v);}}
  async function consultar(){
    var inp=document.getElementById('ecInput'),out=document.getElementById('ecResult');if(!inp||!out)return;
    var bruto=inp.value||'',et='';try{et=norm(typeof window.cleanScanCode==='function'?window.cleanScanCode(bruto):bruto);}catch(e){et=String(bruto).trim().toUpperCase();}
    if(!et){out.innerHTML='<div class="ec-empty">Digite ou bipe o número de uma etiqueta.</div>';return;}
    out.innerHTML='<div class="ec-empty">Consultando a etiqueta <b>'+h(et)+'</b> no catálogo de Bobinas…</div>';
    /* O catálogo grande é carregado do IndexedDB de forma assíncrona. A consulta
       espera essa carga terminar e, se necessário, procura a etiqueta diretamente
       na tabela bobinas da nuvem. Assim ela aparece mesmo sem estar em um depósito. */
    if(!window._bobReady){
      await new Promise(function(resolve){var ini=Date.now(),t=setInterval(function(){if(window._bobReady||Date.now()-ini>2500){clearInterval(t);resolve();}},40);});
    }
    var b=(typeof BOB!=='undefined'&&BOB[et])||null,e=(typeof ETQ!=='undefined'&&ETQ[et])||null;
    if(!b&&typeof window.bobFetch==='function'){
      try{b=await window.bobFetch(et);}catch(_fetchErr){}
      if(b){try{if(typeof saveBOB==='function')saveBOB();}catch(_saveErr){}}
    }
    e=(typeof ETQ!=='undefined'&&ETQ[et])||e||null;
    var mov=[];try{mov=(MV||[]).filter(function(m){return norm(m.et||'')===et;}).sort(function(a,b){return Date.parse(b.at||0)-Date.parse(a.at||0);});}catch(_e){}
    if(!b&&!e&&!mov.length){out.innerHTML='<div class="ec-empty"><b>Etiqueta '+h(et)+' não encontrada</b><br><span>Confira o número ou importe o cadastro de etiquetas.</span></div>';return;}
    var pr=(b&&b.pr)||(e&&e.cProd)||(mov[0]&&mov[0].pr)||'',desc=(b&&b.desc)||(e&&e.xProd)||(typeof descOf==='function'?descOf(pr):'')||'Descrição não informada';
    var qtd=Number((b&&b.pl)||(e&&e.kg)||(mov[0]&&mov[0].q)||0),un=(typeof unitOf==='function'?unitOf(pr):'KG');
    var entrada=mov.find(function(m){return m.action==='entrada'||m.action==='recebimento'||m.action==='armazenar';})||null;
    var ultimo=mov[0]||null,onde=null;try{onde=typeof window.wmsLocalDaEtiqueta==='function'?window.wmsLocalDaEtiqueta(et):null;}catch(_e){}
    var local=onde?(onde.local+(onde.detalhe?' · '+onde.detalhe:'')):'Sem estoque atual';
    var status=onde?'EM ESTOQUE':(ultimo&&ultimo.action==='saida'?'COM SAÍDA':'SEM LOCAL');
    out.innerHTML='<div class="ec-card"><div class="ec-top"><div><div class="ec-et">'+h(et)+'</div><div style="color:var(--muted);font-size:.72rem;margin-top:4px">Consulta completa da bobina</div></div><div class="ec-actions"><span class="ec-status">'+h(status)+'</span><button class="ec-print" type="button" id="ecPrint">Reimprimir etiqueta</button></div></div>'
      +'<div class="ec-grid"><div class="ec-info"><span>Código do material</span><b class="mono">'+h(pr||'—')+'</b></div><div class="ec-info"><span>Descrição</span><b>'+h(desc)+'</b></div><div class="ec-info"><span>Quantidade</span><b>'+h(typeof fmt==='function'?fmt(qtd):qtd)+' '+h(un)+'</b></div><div class="ec-info"><span>Local atual</span><b>'+h(local)+'</b></div><div class="ec-info"><span>Entrada registrada</span><b>'+h(dataHora(entrada&&entrada.at))+'</b></div><div class="ec-info"><span>Recebido/movido por</span><b>'+h((entrada&&entrada.by)||'Não registrado')+'</b></div><div class="ec-info"><span>Último movimento</span><b>'+h(ultimo?String(ultimo.action||'movimento').toUpperCase():'Não registrado')+'</b></div><div class="ec-info"><span>Data do último movimento</span><b>'+h(dataHora(ultimo&&ultimo.at))+'</b></div><div class="ec-info"><span>Documento/Requisição</span><b>'+h((ultimo&&(ultimo.req||ultimo.nf))||'—')+'</b></div></div></div>';
    var imprimir=document.getElementById('ecPrint');if(imprimir)imprimir.onclick=function(){try{if(typeof printBobLabel==='function'){printBobLabel(et);return;}if(typeof stationPrint==='function'){stationPrint({et:et,pr:pr,desc:desc,pl:qtd});return;}toast('Não foi possível preparar a impressão desta etiqueta.',false);}catch(e){toast('Erro ao preparar a impressão.',false);}};
  }
  function renderConsulta(){
    sec.innerHTML='<div class="ec-head"><div class="eb">CADASTRO · RASTREABILIDADE</div><h1>Consulta de Etiqueta</h1><p>Consulte código, descrição, quantidade, entrada e localização atual.</p></div><div class="ec-search"><input class="input" id="ecInput" placeholder="BIPE OU DIGITE A ETIQUETA" autocomplete="off"><button class="ec-go" id="ecGo">Consultar</button></div><div class="ec-result" id="ecResult"><div class="ec-empty">Digite ou bipe uma etiqueta para consultar.</div></div>';
    var i=document.getElementById('ecInput'),b=document.getElementById('ecGo');if(b)b.onclick=consultar;if(i){i.onkeydown=function(ev){if(ev.key==='Enter'){ev.preventDefault();consultar();}};try{if(typeof scanLock==='function')scanLock(i);if(typeof window.addCam==='function')window.addCam('ecInput',{title:'Escanear etiqueta',onResult:function(v){i.value=v;consultar();}});}catch(e){}setTimeout(function(){i.focus();},40);}
  }
  var antigoRender=render;render=function(id){if(id==='v-etqconsulta'){renderConsulta();return;}return antigoRender(id);};window.render=render;
})();

/* ===== CADASTRO DE USUARIO CONFIAVEL =====
   Confirma a persistencia na nuvem e protege a conta contra o pull seguinte. */
(function(){
 var _editUserPersistente=editUser;
 editUser=function(i){
  _editUserPersistente(i);
  var save=document.getElementById('uSave'),login=document.getElementById('uU');
  if(!save||!login)return;
  var saveAnterior=save.onclick;
  save.onclick=async function(ev){
   var nome=String(login.value||'').trim(),nomeLower=nome.toLowerCase();
   var abas=[].slice.call(document.querySelectorAll('[data-uv]:checked')).map(function(c){return c.dataset.uv;});
   var acoes=[].slice.call(document.querySelectorAll('[data-ua]:checked')).map(function(c){return c.dataset.ua;});
   var perfilAtual=String((document.getElementById('uR')||{}).value||'');
   if(perfilAtual!=='admin'&&acoes.indexOf('visualizar')<0)acoes.unshift('visualizar');
   if(nome&&(US||[]).some(function(x,n){return n!==i&&String(x.u||'').trim().toLowerCase()===nomeLower;})){
    toast('Ja existe um usuario com esse login',false);return;
   }
   window._wmsUserWrites=window._wmsUserWrites||{};
   if(nomeLower)window._wmsUserWrites[nomeLower]=Date.now();
   await saveAnterior.call(this,ev);
   var salvo=(US||[]).find(function(x){return String(x.u||'').trim().toLowerCase()===nomeLower;});
   if(!salvo)return;
   if(salvo.role!=='admin'){salvo.views=abas;salvo.actions=acoes;}else{delete salvo.views;delete salvo.actions;}salvo._userUpdated=Date.now();delete salvo._bootstrap;
   DB.saveUsers(US);
   var erro='';
   try{
    if(typeof supa!=='undefined'&&supa){
     var resposta=await supa.from('usuarios').upsert({u:salvo.u,p:salvo.p,role:window.wmsEncodeUserRole(salvo),active:salvo.active!==false});
     if(resposta&&resposta.error)erro=resposta.error.message||'falha ao gravar na nuvem';
    }
   }catch(e){erro=(e&&e.message)||'sem conexao com a nuvem';}
   if(erro)toast('Usuario salvo localmente; sincronizacao pendente: '+erro,false);
   else toast('Usuario criado e pronto para entrar');
  };
 };
 window.editUser=editUser;
})();

